#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Use BFS with visited set to find max removals
// State: current string
// Max string length 100

#define MAXLEN 101
#define HASH_SIZE 1000003

char visited[HASH_SIZE][MAXLEN];
int vis_used[HASH_SIZE];

unsigned int hash_str(const char *s) {
    unsigned int h = 5381;
    while (*s) h = h * 33 + (unsigned char)*s++;
    return h % HASH_SIZE;
}

int in_visited(const char *s) {
    unsigned int h = hash_str(s);
    // linear probe
    while (vis_used[h]) {
        if (strcmp(visited[h], s) == 0) return 1;
        h = (h + 1) % HASH_SIZE;
    }
    return 0;
}

void add_visited(const char *s) {
    unsigned int h = hash_str(s);
    while (vis_used[h]) {
        if (strcmp(visited[h], s) == 0) return;
        h = (h + 1) % HASH_SIZE;
    }
    vis_used[h] = 1;
    strcpy(visited[h], s);
}

// BFS queue
char queue[HASH_SIZE][MAXLEN];
int qhead, qtail;

int main() {
    int size;
    scanf("%d", &size);
    char str[MAXLEN];
    scanf("%s", str);

    int initial_len = strlen(str);
    int max_removed = 0;

    qhead = qtail = 0;
    strcpy(queue[qtail++], str);
    add_visited(str);

    while (qhead < qtail) {
        char cur[MAXLEN];
        strcpy(cur, queue[qhead++]);
        int curlen = strlen(cur);
        int removed = initial_len - curlen;
        if (removed > max_removed) max_removed = removed;

        // Try all valid removals
        for (int i = 0; i < curlen; i++) {
            // Can remove cur[i] if adjacent char is cur[i]-1
            int can_remove = 0;
            if (i > 0 && cur[i-1] == cur[i] - 1) can_remove = 1;
            if (i < curlen-1 && cur[i+1] == cur[i] - 1) can_remove = 1;

            if (can_remove) {
                char next[MAXLEN];
                // Remove position i
                memcpy(next, cur, i);
                strcpy(next + i, cur + i + 1);

                if (!in_visited(next)) {
                    add_visited(next);
                    strcpy(queue[qtail++], next);
                }
            }
        }
    }

    printf("%d\n", max_removed);
    return 0;
}

