import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val parts = br.readLine().trim().split(" ")
    val n = parts[0].toLong()
    val k = parts[1].toLong()

    if (n == 1L) {
        println(0)
        return
    }

    // max total with all k-1 splitters
    // = 1 + k*(k-1)/2
    // Check if possible
    val maxTotal = if (k * (k - 1) / 2 > 2e18.toLong()) Long.MAX_VALUE else 1L + k * (k - 1) / 2

    if (maxTotal < n) {
        println(-1)
        return
    }

    // Binary search on m (number of splitters)
    // f(m) = 1 + m*(k-1) - m*(m-1)/2
    // Need f(m) >= n
    var lo = 0L
    var hi = k - 1

    while (lo < hi) {
        val mid = (lo + hi) / 2
        // compute f(mid), careful of overflow
        val fm = computeF(mid, k)
        if (fm >= n) {
            hi = mid
        } else {
            lo = mid + 1
        }
    }

    println(lo)
}

fun computeF(m: Long, k: Long): Long {
    // f(m) = 1 + m*(k-1) - m*(m-1)/2
    // m can be up to k-1 ~ 1e9, m*(k-1) ~ 1e18 which fits in Long
    // but might overflow, so cap at Long.MAX_VALUE/2
    val cap = Long.MAX_VALUE / 2
    val a = if (m > cap / (k - 1 + 1)) cap else m * (k - 1)
    val b = m * (m - 1) / 2
    return if (a - b + 1 < 0) cap else a - b + 1
}

