Now let me check the bug in the original code. The original code computes `sm` as the count of "less than" constraints, `tot` starts as n-1 and decrements each step. But it seems to use `fac[n-1] * fac[tot] % MOD * inv(fac[sm]) % MOD * inv(fac[tot - sm]) % MOD` which looks like it's computing something wrong.

The correct formula should be: `P(x-1, less) * P(n-x, greater) * (n-1-less-greater)!`

Let me implement this correctly:

```kotlin
fun main() {
    var (n, x, p) = readInts(3)
    // simulate binary search
    var less = 0  // positions that need value < x
    var greater = 0  // positions that need value > x
    var l = 0; var r = n
    while (l < r) {
        val m = (l + r) / 2
        if (m == p) break
        if (m < p) { less++; l = m + 1 }
        else { greater++; r = m }
    }
    // Check feasibility
    if (less > x - 1 || greater > n - x) { println(0); return }
    // P(x-1, less) * P(n-x, greater) * (n-1-less-greater)!
    // ...
}
```

Here's the fixed code:

```kotlin
import java.util.*

val MOD = 1000000007L

fun mpow(x: Long, c: Long): Long {
    var res = 1L; var a = x; var b = c
    while (b > 0) { if (b % 2 == 1L) res = res * a % MOD; a = a * a % MOD; b /= 2 }
    return res
}

fun main() {
    val st = StringTokenizer(readLine())
    val n = st.nextToken().toInt(); val x = st.nextToken().toInt(); val pos = st.nextToken().toInt()
    var less = 0; var greater = 0
    var l = 0; var r = n
    while (l < r) {
        val m = (l + r) / 2
        if (m == pos) break
        if (m < pos) { less++; l = m + 1 } else { greater++; r = m }
    }
    if (less > x - 1 || greater > n - x) { println(0); return }
    val fac = LongArray(n + 1) { 1L }
    for (i in 1..n) fac[i] = fac[i-1] * i % MOD
    var ans = 1L
    // P(x-1, less)
    for (i in 0 until less) ans = ans * ((x - 1 - i).toLong()) % MOD
    // P(n-x, greater)
    for (i in 0 until greater) ans = ans * ((n - x - i).toLong()) % MOD
    // (n-1-less-greater)!
    ans = ans * fac[n - 1 - less - greater] % MOD
    println(ans)
}
