from functools import lru_cache

t = input()
n = len(t)

@lru_cache(maxsize=None)
def solve(pos, at_used):
    if pos == n:
        return "" if at_used else None

    results = []

    # Take single character
    results.append((t[pos], solve(pos + 1, at_used)))

    # Replace "dot" with "."
    if t[pos:pos+3] == "dot":
        results.append((".", solve(pos + 3, at_used)))

    # Replace "at" with "@"
    if not at_used and t[pos:pos+2] == "at":
        results.append(("@", solve(pos + 2, True)))

    # Take "at" as literal characters
    # (already handled by single char above for 'a', then next step handles 't')

    best = None
    for (ch, rest) in results:
        if rest is None:
            continue
        candidate = ch + rest
        if best is None:
            best = candidate
        else:
            # Compare: shorter is better, then lexicographic
            if len(candidate) < len(best):
                best = candidate
            elif len(candidate) == len(best) and candidate < best:
                best = candidate

    return best

