def solve(pos, has_at):
    # Returns list of possible suffixes from position pos
    if pos == n:
        return ['']

    results = []

    # Option 1: take character as-is
    rest = solve(pos + 1, has_at)
    for r in rest:
        results.append(t[pos] + r)

    # Option 2: replace 'dot' with '.'
    if t[pos:pos+3] == 'dot':
        rest = solve(pos + 3, has_at)
        for r in rest:
            results.append('.' + r)

