@lru_cache(maxsize=None)
def solve(pos, at_used):
    if pos == n:
        if not at_used:
            return None  # need exactly one @
        return ""

    options = []

    # Take current char as-is
    rest = solve(pos + 1, at_used)
    if rest is not None:
        options.append(t[pos] + rest)

    # Replace "dot" with "."
    if t[pos:pos+3] == "dot":
        rest = solve(pos + 3, at_used)
        if rest is not None:
            options.append("." + rest)

    # Replace "at" with "@"
    if not at_used and t[pos:pos+2] == "at":
        rest = solve(pos + 2, True)
        if rest is not None:
            options.append("@" + rest)

    if not options:
        return None

    # Pick shortest, then lexicographically smallest
    options.sort(key=lambda x: (len(x), x))
    return options[0]

