from functools import lru_cache

s = raw_input()
n = len(s)

@lru_cache(maxsize=None)
def dp(i, at_used):
    if i == n:
        if at_used == 1:
            return ""
        else:
            return None

    results = []

    # Option 1: take s[i] as-is
    rest = dp(i+1, at_used)
    if rest is not None:
        results.append(s[i] + rest)

    # Option 2: replace 'at' with '@'
    if s[i:i+2] == 'at' and at_used == 0:
        # @ can't be first or last character
        if i > 0 and i+2 < n:  # not first (i>0 means something before), not last (i+2 < n means something after)
            rest2 = dp(i+2, 1)
            if rest2 is not None:
                results.append('@' + rest2)

    # Option 3: replace 'dot' with '.'
    if s[i:i+3] == 'dot':
        # . can't be first or last
        if i > 0 and i+3 < n:
            rest3 = dp(i+3, at_used)
            if rest3 is not None:
                results.append('.' + rest3)

    if not results:
        return None

    # Pick shortest, then lexicographically smallest
    best = min(results, key=lambda x: (len(x), x))
    return best

