import sys
from functools import lru_cache

def solve():
    sys.setrecursionlimit(200000)
    s1 = raw_input().strip()
    s2 = raw_input().strip()
    virus = raw_input().strip()

    l1, l2, lv = len(s1), len(s2), len(virus)

    # Build KMP failure function
    fail = [0] * (lv + 1)
    fail[0] = -1
    j = -1
    for i in range(lv):
        while j >= 0 and virus[j] != virus[i]:
            j = fail[j]
        j += 1
        fail[i+1] = j

    # KMP transition: given state k and character c, return next state
    def kmp_next(k, c):
        while k >= 0 and (k == lv or virus[k] != c):
            if k == 0:
                k = -1
                break
            k = fail[k]
        return k + 1

    # Precompute transitions
    trans = {}
    for k in range(lv):
        for c in set(s1 + s2):
            trans[(k, c)] = kmp_next(k, c)

    # dp[i][j][k] = (length, string) of best LCS from s1[i:], s2[j:] with k virus chars matched
    # Use memoization
    memo = {}

    def dp(i, j, k):
        if k == lv:
            return -1, ""
        if i == l1 or j == l2:
            return 0, ""
        if (i, j, k) in memo:
            return memo[(i, j, k)]

        best_len = 0
        best_str = ""

        # Skip s1[i]
        r1 = dp(i+1, j, k)
        if r1[0] > best_len:
            best_len, best_str = r1

        # Skip s2[j]
        r2 = dp(i, j+1, k)
        if r2[0] > best_len:
            best_len, best_str = r2

        # Match s1[i] == s2[j]
        if s1[i] == s2[j]:
            nk = trans.get((k, s1[i]), kmp_next(k, s1[i]))
            if nk < lv:
                r3 = dp(i+1, j+1, nk)
                if r3[0] != -1:
                    new_len = r3[0] + 1
                    if new_len > best_len:
                        best_len = new_len
                        best_str = s1[i] + r3[1]

        if best_len == 0 and best_str == "":
            memo[(i, j, k)] = (0, "")
        else:
            memo[(i, j, k)] = (best_len, best_str)
        return memo[(i, j, k)]

    ans_len, ans_str = dp(0, 0, 0)
    if ans_len <= 0:
        print(0)
    else:
        print(ans_str)

solve()

