    while j > 0 and virus[i] != virus[j]:
        j = fail[j-1]
    if virus[i] == virus[j]:
        j += 1
    fail[i] = j

# Build KMP transition table
# trans[state][char] = next_state
trans = [[0]*26 for _ in range(lv+1)]
for state in range(lv+1):
    for c in range(26):
        ch = chr(ord('A') + c)
        if state < lv and virus[state] == ch:
            trans[state][c] = state + 1
        elif state == 0:
            trans[state][c] = 0
        else:
            # follow failure links
            j = fail[state-1]
            while j > 0 and virus[j] != ch:
                j = fail[j-1]
            if virus[j] == ch:
                j += 1
            trans[state][c] = j

memo = {}

def dp(i, j, k):
    if k == lv:
        return None  # invalid
    if i == l1 or j == l2:
        return ""
    if (i,j,k) in memo:
        return memo[(i,j,k)]

    best = ""
    # skip s1[i]
    r1 = dp(i+1, j, k)
    if r1 is not None and len(r1) > len(best):
        best = r1
    # skip s2[j]
