from math import sqrt

n, k = [int(i) for i in input().split()]
p = 10 ** 9 + 7

def factorize(n):    
    i = 2
    A = defaultdict(int)

    while n % i == 0:
        n //= i
        A[i] += 1
    i += 1

    while n != 1 and i <= sqrt(n):
        while n % i == 0:
            n //= i
            A[i] += 1
        i += 2
    if n != 1:
        A[n] += 1

    return A

D = dict(factorize(n))
ans = 1
mod = [1, 1]
for i in range(2, 60):
    mod.append(p - (p // i) * mod[p % i] % p)    

for key, v in D.items():
    DP = [[0] * (v+1) for i in range(k+1)]
    DP[0][v] = 1
    for i in range(k):
        for j in range(v+1):
            if DP[i][j] == 0:
                continue
            for l in range(j+1):
                DP[i+1][l] = (DP[i+1][l] + DP[i][j] * mod[j+1]) % p
    res = 0
    pk = 1
    for i in range(v+1):
        res = (res + DP[k][i] * pk) % p
        pk = pk * key % p
    ans = ans * res % p

