def solve():
    x, y, l, r = map(int, raw_input().strip().split())

    # Generate all powers of x <= r
    px = []
    val = 1  # x^0
    while val <= r:
        px.append(val)
        if val > r // x:
            break
        val *= x

    # Generate all powers of y <= r
    py = []
    val = 1  # y^0
    while val <= r:
        py.append(val)
        if val > r // y:
            break
        val *= y

    unlucky = set()
    for a in px:
        for b in py:
            s = a + b
            if l <= s <= r:
                unlucky.add(s)

    sorted_u = sorted([l-1] + list(unlucky) + [r+1])

    max_golden = 0
    for i in range(len(sorted_u)-1):
        gap = sorted_u[i+1] - sorted_u[i] - 1
        if gap > max_golden:
            max_golden = gap

    print max_golden

solve()

