def count_suitable(x):
    # count numbers from 1 to x that are suitable
    # not suitable: x==1, or x%2==0 and x%4!=0, or recursively x/4 not suitable
    # not suitable iff when we remove all factors of 4, we get 1 or 2 mod 4
    not_suit = 0
    # numbers ≡ 2 mod 4 up to x: floor((x-2)/4)+1 if x>=2
    if x >= 2:
        not_suit += (x - 2) // 4 + 1
    # plus 1 for x=1
    if x >= 1:
        not_suit += 1
    # plus multiples of 4 that are not suitable = 4*y where y is not suitable, y <= x//4
    y = x // 4
    if y > 0:
        not_suit += count_not_suitable(y)
    return x - not_suit

